def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    # quick area check
    total_area = sum(a * b for a, b in tiles)
    if total_area < h * w:
        return False

    grid = [[False] * w for _ in range(h)]  # False means empty
    used = [False] * n

    def first_empty():
        for r in range(h):
            for c in range(w):
                if not grid[r][c]:
                    return (r, c)
        return None

    def can_place(r, c, a, b):
        if r + a > h or c + b > w:
            return False
        for i in range(r, r + a):
            for j in range(c, c + b):
                if grid[i][j]:
                    return False
        return True

    def place(r, c, a, b):
        for i in range(r, r + a):
            for j in range(c, c + b):
                grid[i][j] = True

    def remove(r, c, a, b):
        for i in range(r, r + a):
            for j in range(c, c + b):
                grid[i][j] = False

    def backtrack():
        empty = first_empty()
        if empty is None:
            return True
        r, c = empty
        for i in range(n):
            if used[i]:
                continue
            a, b = tiles[i]
            # try both orientations, avoid duplicate if a == b
            orientations = [(a, b)]
            if a != b:
                orientations.append((b, a))
            for a, b in orientations:
                if can_place(r, c, a, b):
                    place(r, c, a, b)
                    used[i] = True
                    if backtrack():
                        return True
                    used[i] = False
                    remove(r, c, a, b)
        return False

    return backtrack()

def count_beautiful_integers(low: int, high: int, k: int) -> int:
    def count_up_to(n):
        if n <= 0:
            return 0
        digits = list(map(int, str(n)))
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def dp(pos, tight, started, diff, mod):
            if pos == len(digits):
                return 1 if (started and diff == 0 and mod == 0) else 0
            limit = digits[pos] if tight else 9
            total = 0
            for d in range(limit + 1):
                new_tight = tight and (d == limit)
                new_started = started or (d != 0)
                new_mod = (mod * 10 + d) % k
                new_diff = diff
                if new_started:
                    if d % 2 == 0:
                        new_diff += 1
                    else:
                        new_diff -= 1
                total += dp(pos + 1, new_tight, new_started, new_diff, new_mod)
            return total
        return dp(0, True, False, 0, 0)
    return count_up_to(high) - count_up_to(low - 1)

