from typing import List, Tuple

def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine if it's possible to perfectly tile an h×w grid using a subset of the given tiles."""

    # Quick area pruning: if total area of all tiles < h*w, impossible
    total_area = sum(a * b for a, b in tiles)
    if total_area < h * w:
        return False

    grid = [[False] * w for _ in range(h)]

    def first_empty_cell():
        for i in range(h):
            for j in range(w):
                if not grid[i][j]:
                    return (i, j)
        return None

    def can_place(r: int, c: int, height: int, width: int) -> bool:
        if r + height > h or c + width > w:
            return False
        for i in range(r, r + height):
            for j in range(c, c + width):
                if grid[i][j]:
                    return False
        return True

    def place_tile(r: int, c: int, height: int, width: int):
        for i in range(r, r + height):
            for j in range(c, c + width):
                grid[i][j] = True

    def remove_tile(r: int, c: int, height: int, width: int):
        for i in range(r, r + height):
            for j in range(c, c + width):
                grid[i][j] = False

    def backtrack(used_mask: int) -> bool:
        cell = first_empty_cell()
        if cell is None:
            return True  # All cells covered

        r, c = cell

        for i in range(n):
            if used_mask & (1 << i):
                continue  # Already used this tile

            a, b = tiles[i]
            # Try both orientations: a×b and b×a
            for height, width in [(a, b), (b, a)]:
                if can_place(r, c, height, width):
                    place_tile(r, c, height, width)
                    if backtrack(used_mask | (1 << i)):
                        return True
                    remove_tile(r, c, height, width)

        return False

    return backtrack(0)


