from typing import List
import math

def kth_smallest_amount(coins: List[int], k: int) -> int:
    if 1 in coins:
        return k
    sorted_coins = sorted(coins)
    filtered = []
    for c in sorted_coins:
        redundant = False
        for f in filtered:
            if c % f == 0:
                redundant = True
                break
        if not redundant:
            filtered.append(c)
    coins = filtered
    n = len(coins)

    def count_leq(X):
        total = 0
        for mask in range(1, 1 << n):
            lcm = 1
            bits = 0
            ok = True
            for i in range(n):
                if mask & (1 << i):
                    c = coins[i]
                    g = math.gcd(lcm, c)
                    if lcm // g > X // c:
                        ok = False
                        break
                    lcm = lcm // g * c
                    bits += 1
            if not ok:
                continue
            cnt = X // lcm
            if bits % 2 == 1:
                total += cnt
            else:
                total -= cnt
        return total

    low = 1
    high = max(coins) * k
    while low < high:
        mid = (low + high) // 2
        if count_leq(mid) >= k:
            high = mid
        else:
            low = mid + 1
    return low
